declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';function gate_assert(bool $c,string $m):void{if(!$c)throw new RuntimeException($m);}$hash=str_repeat('a',64);$ready=['version_capture_status'=>'ready','current_version_id'=>1,'content_hash'=>$hash,'current_version_hash'=>$hash];gate_assert(portal_document_version_delivery_ready($ready),'matching ready binding must deliver');foreach([['version_capture_status'=>'pending','current_version_id'=>null,'content_hash'=>$hash,'current_version_hash'=>''],['version_capture_status'=>'failed','current_version_id'=>null,'content_hash'=>$hash,'current_version_hash'=>''],['version_capture_status'=>'ready','current_version_id'=>0,'content_hash'=>$hash,'current_version_hash'=>$hash],['version_capture_status'=>'ready','current_version_id'=>1,'content_hash'=>$hash,'current_version_hash'=>str_repeat('b',64)]] as $case)gate_assert(!portal_document_version_delivery_ready($case),'unsafe current-version state must not deliver');gate_assert(portal_document_version_delivery_ready([]),'internal pre-catalog path checks remain compatible');$temp=tempnam(sys_get_temp_dir(),'delivery-gate-');$content="verified-handle\0bytes";file_put_contents($temp,$content);$contentHash=hash('sha256',$content);try{$handle=portal_open_verified_document_handle($temp,$contentHash,strlen($content));gate_assert(stream_get_contents($handle)===$content,'verified handle must stream exact hashed bytes');flock($handle,LOCK_UN);fclose($handle);$rejected=false;try{portal_open_verified_document_handle($temp,str_repeat('b',64),strlen($content));}catch(Throwable){$rejected=true;}gate_assert($rejected,'filesystem/hash mismatch must fail closed');}finally{@unlink($temp);}$sync=(string)file_get_contents(dirname(__DIR__).'/scripts/sync_documents.php');$index=(string)file_get_contents(dirname(__DIR__).'/index.php');gate_assert(str_contains($sync,'version_complete')&&str_contains($index,'$versionIncomplete'),'CLI and admin sync must reject incomplete capture with zero failures');echo "[OK] Delivery binds one locked handle to ready version/hash/size; incomplete sync fails closed.\n";
